template <typename Derived>
struct PolymorphicBase {
    // Defines a common interface
    void call_interface() const {
        // Static dispatch via CRTP (zero runtime overhead)
        static_cast<const Derived*>(this)->call_impl();
    }
};

struct OptimizedTypeA : PolymorphicBase<OptimizedTypeA> {
    void call_impl() const {
        // Compiler generates unique code for A
    }
};

struct OptimizedTypeB : PolymorphicBase<OptimizedTypeB> {
    void call_impl() const {
        // Compiler generates unique code for B
    }
};

void usage_example() {
    OptimizedTypeA a;
    a.call_interface(); // Resolved entirely at compile time
}
